package service;

import domain.Note;
import store.FolderStore;
import store.NoteStore;
import sync.IncomingChange;
import sync.PushResult;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/**
 * Devices work offline and upload their edits in batches when they get a connection.
 * After a push the device pulls the change feed, so a change the server keeps
 * ({@link ConflictResolver.Decision#KEEP_SERVER}) is still reported as synced: the device will receive the server copy.
 */
public class SyncService {
    private final NoteStore notes;
    private final FolderStore folders;
    private final ConflictResolver resolver;
    private final ChangeFeed feed;

    public SyncService(NoteStore notes, FolderStore folders, ConflictResolver resolver, ChangeFeed feed) {
        this.notes = notes;
        this.folders = folders;
        this.resolver = resolver;
        this.feed = feed;
    }

    public PushResult push(String deviceId, List<IncomingChange> changes) {
        List<IncomingChange> ordered = new ArrayList<>(changes);
        // a device may queue several edits of the same note; apply them in the order they were made
        ordered.sort(Comparator.comparing(IncomingChange::editedAt));
        List<PushResult.Item> results = new ArrayList<>();
        for (IncomingChange change : ordered) {
            if (change.folderId() != null && folders.find(change.folderId()).isEmpty()) {
                results.add(new PushResult.Item(change.noteId(), PushResult.Status.REJECTED, "unknown folder"));
                continue;
            }
            Note stored = notes.find(change.noteId()).orElse(null);
            switch (resolver.decide(stored, change)) {
                case CREATE -> notes.save(Note.draft(change.noteId(), change.folderId(), change.title(), change.body(), change.editedAt()));
                case APPLY -> notes.save(change.deleted()
                        ? stored.asDeleted(change.editedAt())
                        : stored.withContent(change.title(), change.body(), change.editedAt()));
                case KEEP_SERVER -> {
                }
            }
            results.add(new PushResult.Item(change.noteId(), PushResult.Status.SYNCED, null));
        }
        return new PushResult(List.copyOf(results), feed.currentRevision());
    }
}
package service;

import domain.Note;
import sync.IncomingChange;

/** Whole-note conflicts: the later edit wins, ties keep what the server has. */
public final class ConflictResolver {
    public enum Decision { CREATE, APPLY, KEEP_SERVER }

    public Decision decide(Note stored, IncomingChange change) {
        if (stored == null) {
            return Decision.CREATE;
        }
        if (change.editedAt().isAfter(stored.updatedAt())) {
            return Decision.APPLY;
        }
        return Decision.KEEP_SERVER;
    }
}
package util;

import java.time.DateTimeException;
import java.time.Instant;
import java.time.LocalDateTime;
import java.time.OffsetDateTime;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;

/** Device timestamps arrive as ISO-8601 text, with an offset ("...+09:00", "...Z") or as local time plus a zone. */
public final class Timestamps {
    private Timestamps() {
    }

    public static Instant parse(String text, ZoneId deviceZone) {
        if (text == null || text.isBlank()) {
            throw new IllegalArgumentException("timestamp required");
        }
        String s = text.trim();
        try {
            if (s.endsWith("Z") || s.matches(".*[+-]\\d{2}:\\d{2}$")) {
                return OffsetDateTime.parse(s).toInstant();
            }
            return LocalDateTime.parse(s).atZone(deviceZone).toInstant();
        } catch (DateTimeException e) {
            throw new IllegalArgumentException("bad timestamp: " + text, e);
        }
    }

    public static String format(Instant instant) {
        return instant == null ? null : DateTimeFormatter.ISO_INSTANT.format(instant);
    }
}
package sync;

import java.time.Instant;

/** One note edit made on a device, possibly hours before it is uploaded. */
public record IncomingChange(String noteId, String folderId, String title, String body, Instant editedAt, boolean deleted) {}
package sync;

import java.util.List;

public record PushResult(List<Item> items, long cursor) {
    public enum Status { SYNCED, REJECTED }

    public record Item(String noteId, Status status, String reason) {}
}
package domain;

import java.time.Instant;

/**
 * An inspection note. {@code updatedAt} is when the content last changed;
 * {@code revision} is the server's change counter used by the change feed.
 */
public record Note(String id, String folderId, String title, String body,
                   Instant createdAt, Instant updatedAt, long revision, boolean deleted) implements Audited<Note> {

    public static Note draft(String id, String folderId, String title, String body, Instant updatedAt) {
        return new Note(id, folderId, title, body, null, updatedAt, 0, false);
    }

    public Note withContent(String newTitle, String newBody, Instant changedAt) {
        return new Note(id, folderId, newTitle, newBody, createdAt, changedAt, revision, deleted);
    }

    public Note asDeleted(Instant changedAt) {
        return new Note(id, folderId, title, body, createdAt, changedAt, revision, true);
    }

    public Note movedTo(String newFolderId, Instant changedAt) {
        return new Note(id, newFolderId, title, body, createdAt, changedAt, revision, deleted);
    }

    @Override
    public Note withAudit(Instant created, Instant updated, long rev) {
        return new Note(id, folderId, title, body, created, updated, rev, deleted);
    }
}

