import api.Response;
import app.NotesApp;

import java.util.Map;

public class NotesSyncTest {
    public static void main(String[] args) {
        MutableClock clock = new MutableClock("2026-03-02T08:00:00Z");
        NotesApp app = NotesApp.create(clock);
        String folder = TestSupport.field(app.handle("POST", "/folders", Map.of("name", "Plant 4")), "id");
        Response created = app.handle("POST", "/notes", Map.of("folder", folder, "title", "Pump room", "body", "routine check"));
        TestSupport.check(created.status() == 201, "web console creates a note");
        String note = TestSupport.field(created, "id");

        // web console edit
        clock.set("2026-03-02T08:10:00Z");
        app.handle("PUT", "/notes/" + note, Map.of("body", "routine check, pressure ok"));
        TestSupport.check("routine check, pressure ok".equals(TestSupport.field(app.handle("GET", "/notes/" + note, Map.of()), "body")), "web edit is saved");

        // a note created offline on a device shows up
        clock.set("2026-03-02T08:20:00Z");
        Response first = TestSupport.push(app, "tablet-7", "Asia/Seoul",
                TestSupport.change("dev-7-1", folder, "Boiler", "soot on burner", "2026-03-02T17:05:00"));
        TestSupport.check(first.status() == 200 && first.body().contains("\"status\":\"synced\""), "device push accepted");
        TestSupport.check("soot on burner".equals(TestSupport.field(app.handle("GET", "/notes/dev-7-1", Map.of()), "body")), "note created offline is on the server");

        // two inspectors edited the pump-room note while offline:
        //   tablet-7 at 18:00 Seoul time (09:00 UTC), uploaded at 11:00 UTC
        //   phone-2  at 10:00 UTC,                    uploaded at 11:30 UTC
        clock.set("2026-03-02T11:00:00Z");
        TestSupport.push(app, "tablet-7", "Asia/Seoul",
                TestSupport.change(note, folder, "Pump room", "valve 3 leaking", "2026-03-02T18:00:00"));
        clock.set("2026-03-02T11:30:00Z");
        Response late = TestSupport.push(app, "phone-2", null,
                TestSupport.change(note, folder, "Pump room", "valve 3 replaced, no leak", "2026-03-02T10:00:00Z"));
        TestSupport.check(late.status() == 200, "second device push accepted");

        // an even older offline edit arriving last must not win
        clock.set("2026-03-02T12:00:00Z");
        TestSupport.push(app, "laptop-1", "UTC",
                TestSupport.change(note, folder, "Pump room", "pressure ok", "2026-03-02T08:30:00Z"));

        String body = TestSupport.field(app.handle("GET", "/notes/" + note, Map.of()), "body");
        TestSupport.check(!"pressure ok".equals(body), "an edit made before the others does not replace them");
        TestSupport.check("valve 3 replaced, no leak".equals(body), "the most recent inspection edit is the one shown (got '" + body + "')");

        TestSupport.finish("notes sync");
    }
}
import domain.Note;
import service.ConflictResolver;
import sync.IncomingChange;
import util.FormCodec;
import util.Timestamps;

import java.time.Instant;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.Map;

public class UnitChecks {
    public static void main(String[] args) {
        ZoneId seoul = ZoneId.of("Asia/Seoul");
        TestSupport.check(Timestamps.parse("2026-03-02T18:00:00+09:00", ZoneOffset.UTC).equals(Instant.parse("2026-03-02T09:00:00Z")), "timestamps: explicit offset");
        TestSupport.check(Timestamps.parse("2026-03-02T09:00:00Z", seoul).equals(Instant.parse("2026-03-02T09:00:00Z")), "timestamps: Z ignores device zone");
        TestSupport.check(Timestamps.parse("2026-03-02T18:00:00", seoul).equals(Instant.parse("2026-03-02T09:00:00Z")), "timestamps: local time uses device zone");
        TestSupport.check(Timestamps.parse("2026-07-01T08:30:00", ZoneId.of("Europe/Berlin")).equals(Instant.parse("2026-07-01T06:30:00Z")), "timestamps: summer time");
        boolean threw = false;
        try {
            Timestamps.parse("yesterday", seoul);
        } catch (IllegalArgumentException e) {
            threw = true;
        }
        TestSupport.check(threw, "timestamps: garbage rejected");

        Map<String, String> m = FormCodec.decode(FormCodec.encode(Map.of("body", "a&b=c 100%\nline2")));
        TestSupport.check("a&b=c 100%\nline2".equals(m.get("body")), "form codec: round trip");

        ConflictResolver resolver = new ConflictResolver();
        Note stored = new Note("n", "f", "t", "b", Instant.parse("2026-01-01T00:00:00Z"), Instant.parse("2026-01-01T10:00:00Z"), 3, false);
        TestSupport.check(resolver.decide(null, change("2026-01-01T09:00:00Z")) == ConflictResolver.Decision.CREATE, "resolver: new note");
        TestSupport.check(resolver.decide(stored, change("2026-01-01T10:00:01Z")) == ConflictResolver.Decision.APPLY, "resolver: later edit wins");
        TestSupport.check(resolver.decide(stored, change("2026-01-01T09:59:59Z")) == ConflictResolver.Decision.KEEP_SERVER, "resolver: earlier edit loses");
        TestSupport.check(resolver.decide(stored, change("2026-01-01T10:00:00Z")) == ConflictResolver.Decision.KEEP_SERVER, "resolver: tie keeps server copy");

        TestSupport.finish("unit");
    }

    static IncomingChange change(String at) {
        return new IncomingChange("n", "f", "t2", "b2", Instant.parse(at), false);
    }
}
import api.Request;
import api.Response;
import app.NotesApp;
import util.FormCodec;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

final class TestSupport {
    static int failed = 0;

    private TestSupport() {
    }

    static void check(boolean cond, String msg) {
        System.out.println((cond ? "ok   - " : "FAIL - ") + msg);
        if (!cond) {
            failed++;
        }
    }

    static void finish(String suite) {
        if (failed > 0) {
            System.out.println(suite + ": " + failed + " check(s) failed");
            System.exit(1);
        }
        System.out.println(suite + ": all checks passed");
    }

    static String field(Response r, String name) {
        Matcher m = Pattern.compile("\"" + name + "\":\"((?:[^\"\\\\]|\\\\.)*)\"").matcher(r.body());
        return m.find() ? m.group(1) : null;
    }

    static String change(String id, String folder, String title, String body, String editedAt) {
        Map<String, String> f = new LinkedHashMap<>();
        f.put("id", id);
        f.put("folder", folder);
        f.put("title", title);
        f.put("body", body);
        f.put("editedAt", editedAt);
        return FormCodec.encode(f);
    }

    static Response push(NotesApp app, String device, String zone, String... lines) {
        Map<String, String> headers = new LinkedHashMap<>();
        headers.put("X-Device-Id", device);
        if (zone != null) {
            headers.put("X-Device-Zone", zone);
        }
        return app.handle(new Request("POST", "/sync/push", headers, Map.of(), String.join("\n", lines)));
    }
}
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneId;
import java.time.ZoneOffset;

/** Server clock the test can move forward. */
final class MutableClock extends Clock {
    private volatile Instant now;

    MutableClock(String iso) {
        this.now = Instant.parse(iso);
    }

    void set(String iso) {
        now = Instant.parse(iso);
    }

    @Override
    public ZoneId getZone() {
        return ZoneOffset.UTC;
    }

    @Override
    public Clock withZone(ZoneId zone) {
        return this;
    }

    @Override
    public Instant instant() {
        return now;
    }
}

