        return new Note(id, folderId, newTitle, newBody, createdAt, changedAt, updatedAt, revision, deleted);
    }

    public Note asDeleted(Instant changedAt) {
        return new Note(id, folderId, title, body, createdAt, changedAt, updatedAt, revision, true);
